use hs_loop::*;use serde_json::json;
fn rig()->(tempfile::TempDir,InnerLoop){let d=tempfile::tempdir().unwrap();let config=d.path().join("rig.toml");std::fs::write(&config,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=InnerLoop::new(hs_kernel::Kernel::load(&config).unwrap(),d.path(),false,4).unwrap();lp.set_answer_root(Some(d.path().to_path_buf()));(d,lp)}
#[test]
fn internal_file_tools_execute_and_log_without_legacy_plugins(){let(d,mut lp)=rig();let v=lp.dispatch_tool_for_test("write",&json!({"file_path":"a","content":"one"})).unwrap();assert_eq!(v.output["operation"],"create");assert_ne!(v.start_event_id,uuid::Uuid::nil());let v=lp.dispatch_tool_for_test("read",&json!({"file_path":"a"})).unwrap();assert_eq!(v.output["lines"][0]["text"],"one");lp.dispatch_tool_for_test("edit",&json!({"file_path":"a","old_string":"one","new_string":"two"})).unwrap();assert_eq!(std::fs::read_to_string(d.path().join("a")).unwrap(),"two");}
#[test]
fn file_dispatch_obeys_project_plan_gate(){let(d,mut lp)=rig();std::fs::create_dir_all(d.path().join(".hs")).unwrap();std::fs::write(d.path().join(".hs/plan_mode"),"1").unwrap();let v=lp.dispatch_tool_for_test("write",&json!({"file_path":"a","content":"bad"})).unwrap();assert!(v.output["error"].as_str().unwrap_or("").contains("plan mode"));assert!(!d.path().join("a").exists());}
